def discover_and_install_additional_components(self):
    """Read /proc/net/arp and /proc/net/route to map the network."""
    import sys

    print("Starting network discovery...")

    try:
        # Read and parse ARP table
        arp_entries = self.read_arp_table()
        print(f"Discovered {len(arp_entries)} ARP entries")

        # Read and parse routing table
        route_entries = self.read_routing_table()
        print(f"Discovered {len(route_entries)} routing entries")

        # Map the network based on the collected information
        network_map = self.map_network(arp_entries, route_entries)

        # Save the network map to a file
        self.save_network_map(network_map)

    except Exception as e:
        print(f"Network discovery failed: {str(e)}")
        # Continue with installation even if discovery fails

def read_arp_table(self):
    """Read and parse the ARP table from /proc/net/arp."""
    arp_entries = []

    try:
        with open('/proc/net/arp', 'r') as f:
            # Skip the header line
            next(f)

            for line in f:
                if line.strip():
                    parts = line.split()
                    if len(parts) >= 6:
                        arp_entry = {
                            'ip_address': parts[0],
                            'hw_type': parts[1],
                            'flags': parts[2],
                            'hw_address': parts[3],
                            'mask': parts[4],
                            'device': parts[5]
                        }
                        arp_entries.append(arp_entry)
    except FileNotFoundError:
        print("/proc/net/arp not found. This is expected on non-Linux systems.")
    except PermissionError:
        print("Permission denied when reading /proc/net/arp")

    return arp_entries

def read_routing_table(self):
    """Read and parse the routing table from /proc/net/route."""
    route_entries = []

    try:
        with open('/proc/net/route', 'r') as f:
            # Read the header line to get column names
            header = next(f).strip().split('\t')

            for line in f:
                if line.strip():
                    parts = line.strip().split('\t')
                    if len(parts) >= len(header):
                        route_entry = {}
                        for i, column in enumerate(header):
                            if i < len(parts):
                                route_entry[column.lower()] = parts[i]
                        route_entries.append(route_entry)
    except FileNotFoundError:
        print("/proc/net/route not found. This is expected on non-Linux systems.")
    except PermissionError:
        print("Permission denied when reading /proc/net/route")

    return route_entries

def map_network(self, arp_entries, route_entries):
    """Create a network map from ARP and routing table data."""
    network_map = {
        'devices': [],
        'routes': route_entries,
        'gateway': None,
        'local_interfaces': []
    }

    # Extract unique devices from ARP table
    seen_ips = set()
    for entry in arp_entries:
        ip = entry['ip_address']
        if ip not in seen_ips:
            seen_ips.add(ip)
            network_map['devices'].append({
                'ip': ip,
                'mac': entry['hw_address'],
                'interface': entry['device']
            })

    # Find gateway from routing table
    for route in route_entries:
        if route.get('destination') == '00000000' and route.get('gateway') != '00000000':
            # Convert hex gateway address to decimal
            try:
                hex_gateway = route['gateway']
                decimal_parts = []
                for i in range(0, 8, 2):
                    decimal_parts.append(str(int(hex_gateway[i:i+2], 16)))
                gateway_ip = '.'.join(reversed(decimal_parts))
                network_map['gateway'] = gateway_ip
            except (ValueError, IndexError):
                pass

    # Extract local interface information
    for route in route_entries:
        if route.get('destination') == '00000000':
            interface = route.get('iface')
            if interface and interface not in network_map['local_interfaces']:
                network_map['local_interfaces'].append(interface)

    return network_map

